// Generates supabase/0002_catalog_seed.sql from the bundled fallback catalog.
// Run: node scripts/generate-seed-sql.mjs
import { readFileSync, writeFileSync } from 'node:fs';

const data = JSON.parse(readFileSync(new URL('../src/data/catalog.fallback.json', import.meta.url), 'utf8'));
const q = (value) => (value === null || value === undefined ? 'null' : `'${String(value).replaceAll("'", "''")}'`);

let out = `-- ============================================================================
-- Tokri V2 — catalog seed. Generated by scripts/generate-seed-sql.mjs.
-- Re-run after editing src/data/catalog.fallback.json. Simulated demo prices.
-- ============================================================================

insert into public.stores (id, name, delivery_minutes, delivery_fee, free_above) values
${data.stores.map((s) => `  (${q(s.id)}, ${q(s.name)}, ${s.deliveryMinutes}, ${s.deliveryFee}, ${s.freeAbove})`).join(',\n')}
on conflict (id) do update set name = excluded.name, delivery_minutes = excluded.delivery_minutes,
  delivery_fee = excluded.delivery_fee, free_above = excluded.free_above;

insert into public.products (id, name, category, weight, mrp, barcode, image_url, image_credit_url, unit_qty, unit) values
${data.products.map((p) => `  (${p.id}, ${q(p.name)}, ${q(p.category)}, ${q(p.weight)}, ${p.mrp}, ${q(p.barcode)}, ${q(p.imageUrl)}, ${q(p.imageCreditUrl)}, ${p.unitQty ?? 'null'}, ${q(p.unit)})`).join(',\n')}
on conflict (id) do update set name = excluded.name, category = excluded.category, weight = excluded.weight,
  mrp = excluded.mrp, unit_qty = excluded.unit_qty, unit = excluded.unit,
  barcode = coalesce(excluded.barcode, products.barcode),
  image_url = coalesce(excluded.image_url, products.image_url),
  image_credit_url = coalesce(excluded.image_credit_url, products.image_credit_url);

insert into public.prices (product_id, store_id, price, in_stock) values
${data.products.flatMap((p) => Object.entries(p.prices).map(([storeId, v]) => `  (${p.id}, ${q(storeId)}, ${v.price}, ${v.inStock})`)).join(',\n')}
on conflict (product_id, store_id) do update set price = excluded.price,
  in_stock = excluded.in_stock, updated_at = now();
`;

writeFileSync(new URL('../supabase/0002_catalog_seed.sql', import.meta.url), out);
console.log('wrote supabase/0002_catalog_seed.sql');
